    static IntStream traces(){return IntStream.range(0,16);}static IntStream groups(){return IntStream.range(0,8);}
    static String hex(GamePacket p){return HexFormat.of().formatHex(p.encode());}
    static String text(String s){return new String(HexFormat.of().parseHex(s),StandardCharsets.UTF_8);}
    static List<Scoreboard.Player> actors(LifeHarness h){h.admit(0,2);h.admit(1,2);h.admit(2,3);var old=h.runtime.player(0);h.runtime.disconnected(0);h.admit(0,2);return List.of(new Scoreboard.Player(old),new Scoreboard.Player(h.runtime.player(1)),new Scoreboard.Player(h.runtime.player(2)),new Scoreboard.Player(h.runtime.player(0)));}
    static String state(List<Scoreboard.Player> actors){return String.join("|",actors.stream().map(p->{var s=p.profileStats;String profile=s==null?"-":String.join(",",s.values.entrySet().stream().map(e->e.getKey()+":"+e.getValue().count()+":"+e.getValue().score()).toList())+"@"+s.lastScore;return String.join(";",""+p.score,p.deathPenaltyExempt?"1":"0",p.killBonuses.isEmpty()?"-":String.join(",",p.killBonuses.entrySet().stream().map(e->e.getKey()+":"+(e.getValue().revenge()?1:0)+":"+(e.getValue().payback()?1:0)).toList()),p.roundStats.awards.isEmpty()?"-":String.join(",",p.roundStats.awards.entrySet().stream().map(e->e.getKey()+":"+e.getValue()).toList()),profile);}).toList());}
    static Scoreboard board(Map<Integer,Scoreboard.Player> roster,ProfileTracker profile,List<String> wire,boolean[] fail){return new Scoreboard(()->roster,List::of,Optional::empty,()->false,()->false,new SourceRandom(0),new Scoreboard.Effects(){public void broadcast(GamePacket p,boolean reliable,Integer known){wire.add(hex(p));if(fail[0])throw new IllegalStateException("terminal send fault");}public void scoreChanged(Scoreboard.Player p,int reason){profile.scoreChanged(p,reason);}public void resetProfileBaseline(Scoreboard.Player p){profile.resetBaseline(p);}public void resetResultBaselines(){throw new AssertionError("No result IO");}public void scheduleResults(Integer winner){throw new AssertionError("No result IO");}});}
    static void alive(PlayerLife p,boolean value,Vector at,double now){if(value&&!p.alive())p.spawn(at,now,1,0);if(!value&&p.alive())p.beginDeath(now);p.body().position(at);}
    @ParameterizedTest @MethodSource("traces") void originalGenericEconomyBonusesPenaltiesTeamplayAndFaults(int trace)throws Exception{
        try(var h=new LifeHarness()){
            var actors=actors(h);var p=actors.get(0);var mate=actors.get(1);var victim=actors.get(2);var roster=new LinkedHashMap<Integer,Scoreboard.Player>();for(int i=0;i<3;i++)roster.put(i,actors.get(i));ProfileTracker.Context[] ctx={new ProfileTracker.Context(false,"tdm",false)};GenericEconomy.Context[] gc={new GenericEconomy.Context(ctx[0],true,true)};var profile=new ProfileTracker(()->ctx[0],(a,b)->a.team()!=b.team());var wire=new ArrayList<String>();boolean[] fail={false};var board=board(roster,profile,wire,fail);var economy=new GenericEconomy(()->gc[0],()->roster,board,()->h.monotonic);
            for(var r:Fixtures.rows("match-flow")){if(!r[0].equals("economy")||Integer.parseInt(r[1])!=trace)continue;int step=Integer.parseInt(r[2]),kind=Integer.parseInt(r[3]),owner=Integer.parseInt(r[4]);double age=Fixtures.number(r[5]);ctx[0]=new ProfileTracker.Context(step%31==0,new String[]{"tdm","zom","ugc","TUTORIAL"}[(step/23+trace)%4],step%19==0);gc[0]=new GenericEconomy.Context(ctx[0],step%7!=0,step%5!=0);p.life.bot(step%17==0);p.score=(step*13)%301-70;p.killBonuses.put(victim.id(),new LifeRuntime.Bonus(step%2==0,step%3==0));p.deathPenaltyExempt=step%11==0;victim.diedReloading=step%4==0;double now=100.+step*.25;alive(mate.life,true,new Vector(36,36,97),now);mate.life.endProtection(now);victim.life.endProtection(now);mate.life.damageHistory().clear();h.monotonic=now-age;if(step%6!=0){mate.life.health(100);h.runtime.damage(1,1,2,0);assertEquals(1,mate.life.damageHistory().snapshot().size());}h.monotonic=now;alive(mate.life,step%9!=0,new Vector(36,36,97),now);roster.remove(0);if(owner!=1)roster.put(0,owner==0?p:actors.get(3));wire.clear();fail[0]=r[6].equals("1");String result;
                try{long paid=switch(step%3){case 0->economy.kill(p,victim,kind,step%4==0);case 1->economy.deathPenalty(p,new Scoreboard.Player[]{p,victim,null,mate}[(step/3+trace)%4],kind);default->economy.teamplay(p,victim);};result=""+paid;}catch(IllegalStateException e){result="RuntimeError";}
                String where="economy "+trace+":"+step;assertEquals(r[7],result,where);assertEquals(r[8],state(actors),where+" state");assertEquals(r[9],String.join(",",wire),where+" wire");
            }
        }
    }
    @ParameterizedTest @MethodSource("traces") void originalTeabagPressTimingDeathKeysProfilesAndRules(int trace)throws Exception{
        try(var h=new LifeHarness()){
            var actors=actors(h);var p=actors.get(0);var victim=actors.get(2);var roster=new LinkedHashMap<Integer,Scoreboard.Player>();for(int i=0;i<3;i++)roster.put(i,actors.get(i));ProfileTracker.Context[] ctx={new ProfileTracker.Context(false,"tdm",false)};boolean[] retiring={false},classic={false},points={false},fail={false},ruleFault={false};var profile=new ProfileTracker(()->ctx[0],(a,b)->a.team()!=b.team());var wire=new ArrayList<String>();var board=board(roster,profile,wire,fail);var objective=new ObjectiveScores(()->ctx[0],()->retiring[0],()->roster,board);var bag=new TeabagTracker(()->roster,objective,profile,()->classic[0],()->{if(ruleFault[0])throw new IllegalStateException("controlled rule-service read fault");return points[0];});
            for(var r:Fixtures.rows("match-flow")){if(!r[0].equals("teabag")||Integer.parseInt(r[1])!=trace)continue;int step=Integer.parseInt(r[2]);double now=Fixtures.number(r[3]),death=Fixtures.number(r[6]);var at=Fixtures.vector(r[4]);var spot=Fixtures.vector(r[5]);ctx[0]=new ProfileTracker.Context(false,step%19==0?new String[]{"tdm","cctf","ugc","TUTORIAL"}[trace%4]:"tdm",step%37==0);retiring[0]=step%41==0;classic[0]=(step/9+trace)%2!=0||step%11==0;points[0]=r[7].equals("1");ruleFault[0]=step%27==0;p.life.bot(step%17==0);alive(p.life,step%29!=0,at,now);
                boolean liveVictim=step%23==0;if(victim.life.deathTime()!=death||!liveVictim&&victim.life.alive()){alive(victim.life,true,spot,now);victim.life.beginDeath(death);}if(liveVictim&&!victim.life.alive())victim.life.spawn(spot,now,1,0);victim.life.body().position(spot);wire.clear();fail[0]=r[8].equals("1");String result;try{result=bag.crouch(p,now)?"True":"False";}catch(IllegalStateException e){result="RuntimeError";}
                String where="teabag "+trace+":"+step;assertEquals(r[9],result,where);assertEquals(r[10],bag.presses(p).isEmpty()?"-":String.join(",",bag.presses(p).stream().map(Fixtures::bits).toList()),where+" presses");assertEquals(Integer.parseInt(r[11]),bag.completed(p),where+" death keys");assertEquals(r[12],state(actors),where+" state");assertEquals(r[13],String.join(",",wire),where+" wire");
            }
        }
    }
    @ParameterizedTest @MethodSource("traces") void originalNativeEscapeClassificationTrackingModeOwnershipAndReplay(int trace)throws Exception{
        try(var h=new LifeHarness()){
            h.admit(0,2);PlayerLife[] p={h.runtime.player(0)};var roster=new LinkedHashMap<Integer,PlayerLife>();roster.put(0,p[0]);boolean[] marked={false},objective={false},predicateFault={false},objectiveFault={false};var modes=new EscapeWatch.Mode[2];for(int i=0;i<2;i++)modes[i]=new EscapeWatch.Mode(){public boolean enabled(){return true;}public boolean marks(PlayerLife actor){if(predicateFault[0])throw new IllegalStateException("observer fault");return marked[0];}public boolean objective(PlayerLife actor){if(objectiveFault[0])throw new IllegalStateException("observer fault");return objective[0];}};EscapeWatch.Mode[] mode={modes[0]};EscapeWatch.Settings[] settings={EscapeWatch.Settings.defaults()};var wire=new ArrayList<String>();var watch=new EscapeWatch(h.world,()->settings[0],()->roster,()->Optional.of(mode[0]),packet->wire.add(hex(packet)));
            for(var r:Fixtures.rows("match-flow")){if(!r[0].equals("edit")&&!r[0].equals("escape")||Integer.parseInt(r[1])!=trace)continue;if(r[0].equals("edit")){h.world.set(new MutableWorld.Cell(Integer.parseInt(r[2]),Integer.parseInt(r[3]),Integer.parseInt(r[4])),r[5].equals("1"),0x808080,null);continue;}int step=Integer.parseInt(r[2]),action=Integer.parseInt(r[8]);double now=Fixtures.number(r[3]);predicateFault[0]=step%17==0;objectiveFault[0]=step%19==0;var at=Fixtures.vector(r[4]);marked[0]=r[5].equals("1");objective[0]=r[6].equals("1");settings[0]=new EscapeWatch.Settings(step%29!=0,new double[]{.1,1,2,Double.NaN}[trace%4],1+trace%4,trace%3,trace%5);if(action==0)mode[0]=modes[step/23%2];if(action==1){h.runtime.disconnected(0);h.admit(0,2);p[0]=h.runtime.player(0);roster.put(0,p[0]);}if(action==2)roster.remove(0);else if(action==3)roster.put(0,p[0]);alive(p[0],step%31!=0,at,now);h.runtime.input(0,new LiveClientInput(step+1,0,false,6,1,0,0,0,step%2==0?32:0,0,0),0);wire.clear();if(action==4)watch.forget(p[0]);else if(action==5)watch.reveal(packet->wire.add("L"+hex(packet)));else watch.tick(Optional.empty(),now,r[7].equals("1"));String snapshot=watch.initialized()?Fixtures.bits(watch.nextCheck())+";"+String.join("|",watch.snapshots().stream().map(t->t.player().id()+","+(t.condition()==null?"-":t.condition())+","+Fixtures.bits(t.since())+","+(t.flagged()==null?"-":t.flagged())+","+t.cleanChecks()+","+(t.modeMarked()?1:0)).toList()):"-";
                String where="escape "+trace+":"+step;assertEquals(r[9],Objects.requireNonNullElse(watch.classify(at,step%2==0,objective[0]),"-"),where+" classification");assertEquals(r[10].equals("1"),watch.sealed(at,new int[]{0,1,48,256}[step%4]),where+" sealed");assertEquals(r[11].equals("1"),watch.embedded(at),where+" embedded");assertEquals(r[12],snapshot,where+" tracks");assertEquals(r[13],Objects.requireNonNullElse(watch.flagged(p[0]),"-"),where+" flag");assertEquals(r[14],String.join(",",wire),where+" native marker wire");
            }
        }
    }
    @ParameterizedTest @MethodSource("traces") void originalClockCountdownAndSimulationTimeoutRemainder(int trace)throws Exception{
        var wire=new ArrayList<String>();var events=new ArrayList<String>();var teams=List.of(new TeamState(2,"Blue",0,0,0),new TeamState(3,"Green",0,0,0));teams.get(0).score=trace%3;teams.get(1).score=trace%2;RoundClock[] clock={null};double[] now={0};int queued=0;
        var effects=new RoundClock.Effects(){public void escapeWatch(){throw new AssertionError("Explicitly disabled watch in this source clock trace");}public void escapeFailure(RuntimeException e){throw new AssertionError(e);}public void timeoutMusic(){events.add("M");}public void announce(FlowCatalog.Cue cue){wire.add(hex(Announcements.localised(cue.stringId(),cue.parameters(),false,true)));}public void ensureVote(double wall){events.add("V:"+Fixtures.bits(wall));}public CompletionStage<Void> endByTime(){if(clock[0].ended||clock[0].retiring)return CompletableFuture.completedFuture(null);Integer winner=RoundClock.timeWinner(teams);wire.add(hex(Announcements.localised(winner==null?"GAME_DRAWN":"TEAM_DEFEAT",winner==null?List.of():List.of(teams.stream().filter(t->t.id==winner).findFirst().orElseThrow().name),winner!=null,false)));clock[0].ended=true;events.add("E:"+Fixtures.bits(now[0]));return CompletableFuture.completedFuture(null);}};
        for(var r:Fixtures.rows("match-flow")){if(!r[0].equals("clock")||Integer.parseInt(r[1])!=trace)continue;int step=Integer.parseInt(r[2]),op=Integer.parseInt(r[3]);now[0]=Fixtures.number(r[4]);if(op==0){clock[0]=new RoundClock(effects);clock[0].reset(now[0]);clock[0].escapeEnabled=false;queued=0;}clock[0].timeLimit=Fixtures.number(r[5]);clock[0].retiring=step%47==0;if(op==1)clock[0].countdown(Fixtures.number(r[6]));else{queued+=(step+trace)%5;int budget=clock[0].drainBudget(queued,3);for(int i=0;i<budget;i++)events.add("P");queued-=budget;clock[0].drained(budget);clock[0].tick(now[0],queued).toCompletableFuture().join();}String snapshot=String.join(";",Fixtures.bits(clock[0].elapsed),clock[0].ended?"1":"0",clock[0].timeoutMusicPlayed?"1":"0",clock[0].timeoutRemaining()==null?"-":""+clock[0].timeoutRemaining(),Fixtures.bits(clock[0].lastRemaining()),clock[0].fired().isEmpty()?"-":String.join(",",clock[0].fired().stream().sorted().map(Fixtures::bits).toList()),""+queued);String where="clock "+trace+":"+step;assertEquals(r[7],snapshot,where+" state");assertEquals(r[8],String.join(",",wire),where+" native announcements");assertEquals(r[9],String.join(",",events),where+" terminal music/vote/plugin boundaries");assertEquals(r[10],Objects.toString(RoundClock.scoreWinner(teams,new int[]{0,1,2,10}[step%4]),"-"));assertEquals(Integer.parseInt(r[11]),RoundClock.headline(new Integer[]{null,2,3,7}[step%4],teams.get(0).score,teams.get(1).score));wire.clear();events.clear();}
    }
    @ParameterizedTest @MethodSource("groups") void originalMarkerAndLocalisedCodecs(int group)throws Exception{assertTrue(PacketCodec.supports(17)&&PacketCodec.supports(50));for(var r:Fixtures.rows("match-flow")){if(!(r[0].equals("marker")||r[0].equals("local"))||Integer.parseInt(r[1])/64!=group)continue;GamePacket packet=r[0].equals("marker")?new MatchPackets.ChangePlayer(Integer.parseInt(r[2]),Integer.parseInt(r[3]),Integer.parseInt(r[4])):new MatchPackets.LocalisedMessage(Integer.parseInt(r[2]),Integer.parseInt(r[3]),text(r[5]),IntStream.range(0,Integer.parseInt(r[6])).mapToObj(i->"p"+i).toList(),Integer.parseInt(r[4]));int encoded=r[0].equals("marker")?5:7;assertEquals(r[encoded],hex(packet),r[0]+r[1]);assertEquals(r[encoded+1],hex(PacketCodec.decode(HexFormat.of().parseHex(r[encoded]))));}}
    @ParameterizedTest @MethodSource("traces") void originalBoundedHudBuildersUnicodeAndNames(int group)throws Exception{for(var r:Fixtures.rows("match-flow")){if(!r[0].equals("announcement")||Integer.parseInt(r[1])/64!=group)continue;int n=Integer.parseInt(r[1]);String overlay,local;try{overlay=hex(Announcements.overlay(text(r[2])));}catch(IllegalArgumentException e){overlay="ValueError";}try{local=hex(Announcements.localised(text(r[3]),Collections.nCopies(Integer.parseInt(r[4]),"2"),n%2==0,n%3==0));}catch(IllegalArgumentException e){local="ValueError";}assertEquals(r[5],overlay,"overlay "+n);assertEquals(r[6],local,"local "+n);assertEquals(text(r[7]),Announcements.safeName(text(r[2])));}}
    @ParameterizedTest @MethodSource("groups") void originalEmptySoleMultiTeamTimeoutAndScoreWinners(int group)throws Exception{for(var r:Fixtures.rows("match-flow")){if(!r[0].equals("winner")||Integer.parseInt(r[1])/64!=group)continue;var teams=new ArrayList<TeamState>();if(!r[3].equals("-"))for(var item:r[3].split(",")){var parts=item.split(":");var t=new TeamState(Integer.parseInt(parts[0]),"Team"+parts[0],0,0,0);t.score=Long.parseLong(parts[1]);teams.add(t);}assertEquals(r[4],Objects.toString(RoundClock.scoreWinner(teams,Long.parseLong(r[2])),"-"));Integer winner=RoundClock.timeWinner(teams);assertEquals(r[5],Objects.toString(winner,"-"));var packet=Announcements.localised(winner==null?"GAME_DRAWN":"TEAM_DEFEAT",winner==null?List.of():List.of("Team"+winner),winner!=null,false);assertEquals(r[6],hex(packet));}}
